BEGIN;

UPDATE public.questions q
SET explanation_data = q.explanation_data || jsonb_build_object('viz', '<svg viewBox="0 0 340 170" xmlns="http://www.w3.org/2000/svg"><text x="170" y="14" font-size="8.5" fill="#e8eaf0" text-anchor="middle" font-weight="600">マネージャーが落ちても、動作中タスクは止まらない</text><rect x="120" y="28" width="100" height="26" rx="4" fill="#241a1a" stroke="#c47070" stroke-width="1"/><text x="170" y="42" font-size="8.5" fill="#c47070" text-anchor="middle" font-weight="normal">マネージャー</text><text x="170" y="52" font-size="6.5" fill="#8892a4" text-anchor="middle" font-weight="normal">停止中（判断役が不在）</text><rect x="20" y="76" width="90" height="60" rx="4" fill="#1a1e29" stroke="#2a2f3f" stroke-width="1"/><text x="65" y="90" font-size="8" fill="#8892a4" text-anchor="middle" font-weight="normal">ワーカー1</text><rect x="32" y="100" width="66" height="24" rx="4" fill="#232a1f" stroke="#6ab08d" stroke-width="1"/><text x="65" y="115" font-size="7.5" fill="#6ab08d" text-anchor="middle" font-weight="normal">実行継続中</text><rect x="130" y="76" width="90" height="60" rx="4" fill="#1a1e29" stroke="#2a2f3f" stroke-width="1"/><text x="175" y="90" font-size="8" fill="#8892a4" text-anchor="middle" font-weight="normal">ワーカー2</text><rect x="142" y="100" width="66" height="24" rx="4" fill="#232a1f" stroke="#6ab08d" stroke-width="1"/><text x="175" y="115" font-size="7.5" fill="#6ab08d" text-anchor="middle" font-weight="normal">実行継続中</text><rect x="240" y="76" width="90" height="60" rx="4" fill="#1a1e29" stroke="#2a2f3f" stroke-width="1"/><text x="285" y="90" font-size="8" fill="#8892a4" text-anchor="middle" font-weight="normal">ワーカー3</text><rect x="252" y="100" width="66" height="24" rx="4" fill="#232a1f" stroke="#6ab08d" stroke-width="1"/><text x="285" y="115" font-size="7.5" fill="#6ab08d" text-anchor="middle" font-weight="normal">実行継続中</text><line x1="170" y1="54" x2="170" y2="76" stroke="#2a2f3f" stroke-width="1" stroke-dasharray="2,2"/><text x="170" y="148" font-size="8" fill="#c9a04a" text-anchor="middle" font-weight="normal">できる: 既存タスクの実行　できない: 新規スケジューリング・再配置</text></svg>')
WHERE q.source_ref = 'dca-q1'
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'dca');

UPDATE public.questions q
SET explanation_data = q.explanation_data || jsonb_build_object('viz', '<svg viewBox="0 0 340 178" xmlns="http://www.w3.org/2000/svg"><text x="170" y="14" font-size="8.7" fill="#e8eaf0" text-anchor="middle" font-weight="600">global は全ノードに1個、replicated は合計N個</text><text x="85" y="30" font-size="8.5" fill="#60a5fa" text-anchor="middle" font-weight="600">global（3ノード）</text><rect x="8" y="40" width="45" height="46" rx="4" fill="#1a1e29" stroke="#2a2f3f" stroke-width="1"/><text x="30.5" y="52" font-size="7.5" fill="#8892a4" text-anchor="middle" font-weight="normal">N1</text><rect x="13" y="60" width="35" height="20" rx="4" fill="#20263a" stroke="#3b82f6" stroke-width="1"/><text x="30.5" y="73" font-size="7.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">1個</text><rect x="60" y="40" width="45" height="46" rx="4" fill="#1a1e29" stroke="#2a2f3f" stroke-width="1"/><text x="82.5" y="52" font-size="7.5" fill="#8892a4" text-anchor="middle" font-weight="normal">N2</text><rect x="65" y="60" width="35" height="20" rx="4" fill="#20263a" stroke="#3b82f6" stroke-width="1"/><text x="82.5" y="73" font-size="7.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">1個</text><rect x="112" y="40" width="45" height="46" rx="4" fill="#1a1e29" stroke="#2a2f3f" stroke-width="1"/><text x="134.5" y="52" font-size="7.5" fill="#8892a4" text-anchor="middle" font-weight="normal">N3</text><rect x="117" y="60" width="35" height="20" rx="4" fill="#20263a" stroke="#3b82f6" stroke-width="1"/><text x="134.5" y="73" font-size="7.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">1個</text><text x="255" y="30" font-size="8.5" fill="#6ab08d" text-anchor="middle" font-weight="600">replicated（合計4）</text><rect x="180" y="40" width="45" height="46" rx="4" fill="#1a1e29" stroke="#2a2f3f" stroke-width="1"/><text x="202.5" y="52" font-size="7.5" fill="#8892a4" text-anchor="middle" font-weight="normal">N1</text><rect x="185" y="60" width="14" height="20" rx="4" fill="#232a1f" stroke="#6ab08d" stroke-width="1"/><rect x="202" y="60" width="14" height="20" rx="4" fill="#232a1f" stroke="#6ab08d" stroke-width="1"/><rect x="232" y="40" width="45" height="46" rx="4" fill="#1a1e29" stroke="#2a2f3f" stroke-width="1"/><text x="254.5" y="52" font-size="7.5" fill="#8892a4" text-anchor="middle" font-weight="normal">N2</text><rect x="237" y="60" width="14" height="20" rx="4" fill="#232a1f" stroke="#6ab08d" stroke-width="1"/><rect x="284" y="40" width="45" height="46" rx="4" fill="#1a1e29" stroke="#2a2f3f" stroke-width="1"/><text x="306.5" y="52" font-size="7.5" fill="#8892a4" text-anchor="middle" font-weight="normal">N3</text><rect x="289" y="60" width="14" height="20" rx="4" fill="#232a1f" stroke="#6ab08d" stroke-width="1"/><text x="170" y="118" font-size="8" fill="#8892a4" text-anchor="middle" font-weight="normal">global: 監視エージェントなど「全ノードに必ず1つ」欲しい用途</text><text x="170" y="132" font-size="8" fill="#8892a4" text-anchor="middle" font-weight="normal">replicated: Webサーバなど「合計いくつ」だけ決めて</text><text x="170" y="144" font-size="8" fill="#8892a4" text-anchor="middle" font-weight="normal">配置先はスケジューラに任せる用途</text></svg>')
WHERE q.source_ref = 'dca-q4'
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'dca');

UPDATE public.questions q
SET explanation_data = q.explanation_data || jsonb_build_object('viz', '<svg viewBox="0 0 340 168" xmlns="http://www.w3.org/2000/svg"><text x="170" y="14" font-size="9" fill="#e8eaf0" text-anchor="middle" font-weight="600">unhealthy を検知したら、望む状態へ戻す</text><rect x="12" y="40" width="72" height="34" rx="4" fill="#232a1f" stroke="#6ab08d" stroke-width="1"/><text x="48.0" y="54" font-size="7" fill="#e8eaf0" text-anchor="middle" font-weight="normal">正常稼働</text><text x="48.0" y="65" font-size="6" fill="#8892a4" text-anchor="middle" font-weight="normal"></text><line x1="85" y1="57" x2="89" y2="57" stroke="#8892a4" stroke-width="1.2"/><rect x="90" y="40" width="72" height="34" rx="4" fill="#241a1a" stroke="#c47070" stroke-width="1"/><text x="126.0" y="54" font-size="7" fill="#e8eaf0" text-anchor="middle" font-weight="normal">HEALTHCHECK失敗</text><text x="126.0" y="65" font-size="6" fill="#8892a4" text-anchor="middle" font-weight="normal"></text><line x1="163" y1="57" x2="167" y2="57" stroke="#8892a4" stroke-width="1.2"/><rect x="168" y="40" width="72" height="34" rx="4" fill="#2a2416" stroke="#c9a04a" stroke-width="1"/><text x="204.0" y="54" font-size="7" fill="#e8eaf0" text-anchor="middle" font-weight="normal">そのタスクを終了</text><text x="204.0" y="65" font-size="6" fill="#8892a4" text-anchor="middle" font-weight="normal"></text><line x1="241" y1="57" x2="245" y2="57" stroke="#8892a4" stroke-width="1.2"/><rect x="246" y="40" width="72" height="34" rx="4" fill="#20263a" stroke="#60a5fa" stroke-width="1"/><text x="282.0" y="54" font-size="7" fill="#e8eaf0" text-anchor="middle" font-weight="normal">新タスクを起動</text><text x="282.0" y="65" font-size="6" fill="#8892a4" text-anchor="middle" font-weight="normal"></text><line x1="320" y1="57" x2="330" y2="57" stroke="#8892a4" stroke-width="1"/><line x1="330" y1="57" x2="330" y2="100" stroke="#8892a4" stroke-width="1"/><line x1="330" y1="100" x2="12" y2="100" stroke="#8892a4" stroke-width="1"/><line x1="12" y1="100" x2="12" y2="57" stroke="#8892a4" stroke-width="1"/><text x="170" y="122" font-size="8" fill="#8892a4" text-anchor="middle" font-weight="normal">「宣言した数だけ健全なタスクを保つ」をSwarmが常に</text><text x="170" y="135" font-size="8" fill="#8892a4" text-anchor="middle" font-weight="normal">自動で守り続ける（宣言的収束）。人が再起動しなくてよい</text></svg>')
WHERE q.source_ref = 'dca-q79'
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'dca');

UPDATE public.questions q
SET explanation_data = q.explanation_data || jsonb_build_object('viz', '<svg viewBox="0 0 340 168" xmlns="http://www.w3.org/2000/svg"><text x="170" y="14" font-size="9.5" fill="#e8eaf0" text-anchor="middle" font-weight="600">drain：タスクを逃がして、空にする</text><rect x="15" y="30" width="130" height="70" rx="4" fill="#241a1a" stroke="#c47070" stroke-width="1"/><text x="80" y="44" font-size="8.5" fill="#c47070" text-anchor="middle" font-weight="600">ノードA</text><text x="80" y="55" font-size="7" fill="#8892a4" text-anchor="middle" font-weight="normal">--availability drain</text><rect x="30" y="62" width="100" height="20" rx="4" fill="#1a1e29" stroke="#2a2f3f" stroke-width="1"/><text x="80" y="75" font-size="7.5" fill="#8892a4" text-anchor="middle" font-weight="normal">タスク退避済み</text><text x="80" y="92" font-size="7" fill="#c47070" text-anchor="middle" font-weight="normal">新規タスクも来ない</text><rect x="195" y="30" width="130" height="70" rx="4" fill="#232a1f" stroke="#6ab08d" stroke-width="1"/><text x="260" y="44" font-size="8.5" fill="#6ab08d" text-anchor="middle" font-weight="600">ノードB</text><text x="260" y="55" font-size="7" fill="#8892a4" text-anchor="middle" font-weight="normal">active</text><rect x="210" y="62" width="45" height="20" rx="4" fill="#20263a" stroke="#3b82f6" stroke-width="1"/><text x="232.5" y="75" font-size="7.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">既存</text><rect x="260" y="62" width="45" height="20" rx="4" fill="#20263a" stroke="#3b82f6" stroke-width="1"/><text x="282.5" y="75" font-size="7.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">退避先</text><line x1="90" y1="72" x2="210" y2="72" stroke="#c9a04a" stroke-width="1.3"/><text x="150" y="66" font-size="7" fill="#c9a04a" text-anchor="middle" font-weight="normal">再配置</text><text x="170" y="130" font-size="8" fill="#8892a4" text-anchor="middle" font-weight="normal">メンテナンスでノードを止めたい前に使う。</text><text x="170" y="143" font-size="8" fill="#8892a4" text-anchor="middle" font-weight="normal">サービスを止めずに安全に切り離せる</text></svg>')
WHERE q.source_ref = 'dca-q80'
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'dca');

UPDATE public.questions q
SET explanation_data = q.explanation_data || jsonb_build_object('viz', '<svg viewBox="0 0 340 178" xmlns="http://www.w3.org/2000/svg"><text x="170" y="14" font-size="8.3" fill="#e8eaf0" text-anchor="middle" font-weight="600">constraint は必須の壁、placement-pref は好みの傾き</text><text x="85" y="30" font-size="8.5" fill="#c47070" text-anchor="middle" font-weight="600">--constraint（必須）</text><rect x="20" y="40" width="130" height="22" rx="4" fill="#241a1a" stroke="#c47070" stroke-width="1"/><text x="85" y="54" font-size="7.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">条件に合わないノードは除外</text><rect x="20" y="68" width="44" height="20" rx="4" fill="#232a1f" stroke="#6ab08d" stroke-width="1"/><text x="42" y="81" font-size="7" fill="#e8eaf0" text-anchor="middle" font-weight="normal">配置可</text><rect x="72" y="68" width="44" height="20" rx="4" fill="#1a1e29" stroke="#2a2f3f" stroke-width="1"/><text x="94" y="81" font-size="7" fill="#8892a4" text-anchor="middle" font-weight="normal">対象外</text><rect x="124" y="68" width="44" height="20" rx="4" fill="#232a1f" stroke="#6ab08d" stroke-width="1"/><text x="146" y="81" font-size="7" fill="#e8eaf0" text-anchor="middle" font-weight="normal">配置可</text><text x="255" y="30" font-size="8.5" fill="#c9a04a" text-anchor="middle" font-weight="600">--placement-pref（優先度）</text><rect x="190" y="40" width="140" height="22" rx="4" fill="#2a2416" stroke="#c9a04a" stroke-width="1"/><text x="260" y="54" font-size="7.5" fill="#e8eaf0" text-anchor="middle" font-weight="normal">全ノードが対象。均等寄りに配る</text><rect x="190" y="72" width="46" height="16" rx="4" fill="#20263a" stroke="#3b82f6" stroke-width="1"/><rect x="244" y="68" width="42" height="20" rx="4" fill="#20263a" stroke="#3b82f6" stroke-width="1"/><rect x="286" y="74" width="44" height="14" rx="4" fill="#20263a" stroke="#3b82f6" stroke-width="1"/><text x="170" y="120" font-size="8" fill="#8892a4" text-anchor="middle" font-weight="normal">constraint: 満たさなければ絶対に置かない</text><text x="170" y="133" font-size="8" fill="#8892a4" text-anchor="middle" font-weight="normal">placement-pref: 満たせなくても置く、傾斜をかけるだけ</text></svg>')
WHERE q.source_ref = 'dca-q81'
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'dca');

COMMIT;